23	            throws OwnerFieldsValidationException {
24	        List<String> errors = new ArrayList<>();
25	        requireText("firstName", request.getFirstName(), errors);
26	        requireText("lastName", request.getLastName(), errors);
27	        requireText("address", request.getAddress(), errors);
28	        requireText("city", request.getCity(), errors);
