40	     * and return it. A leading {@code +} and its country code are kept; otherwise country code
41	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
42	     * Spaces, dashes and brackets are stripped, and the result must carry 8 to 15 digits after the
43	     * {@code +}. So {@code "0412 345 678"} becomes {@code "+61412345678"}. A number that cannot form
44	     * valid E.164 adds a {@code telephone} error (400). Skipped when the telephone is missing/blank,
45	     * which {@link #requireText} has already flagged.
46	     */
47	    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
48	        String telephone = request.getTelephone();
49	        if (telephone == null || telephone.isBlank()) {
50	            return;
51	        }
52	        String e164 = toE164(telephone);
53	        if (e164 == null) {
54	            errors.add("telephone");
